ave_v=sum(abs(v_other))/(nv-1);
ave_distance=sum(abs(vi-v_other))/(nv-1);

cur_pos=rtk.ins.pos;     cur_rr=blh2xyz(cur_pos);
cur_pos=rtk.ins.pos;     cur_rr=blh2xyz(cur_pos);
cur_rr=rtk.basepos;  cur_pos=xyz2blh(cur_rr);
old_rr=cur_rr;       old_pos=cur_pos;
