%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
stat=0; MAXITER=10; iter=1; 
vel0=rtk.ins.vel; pos=rtk.ins.x(7:9);  [~,Cen]=blh2xyz(pos);
