    for i=1:3
        rtk=initx(rtk,rtk.sol.pos(i),VAR_POS,i);
    end
    if rtk.opt.dynamics==1
        for i=1:3
            rtk=initx(rtk,rtk.sol.vel(i),VAR_VEL,3+i);
        end
        for i=1:3
            rtk=initx(rtk,1e-6,VAR_ACC,6+i);
        end
    end
end

