    for i=1:3
        rtk.P(i,i)=rtk.P(i,i)+(rtk.opt.prn(6))^2*abs(rtk.tt);
    end
    return;
end

% kinmatic without dynamics
if rtk.opt.dynamics==0
    for i=1:3
        rtk=initx(rtk,rtk.sol.pos(i),VAR_POS,i);
    end
    return;
end

% generate valid state index
nx=1;
for i=1:rtk.nx
    if rtk.x(i)~=0&&rtk.P(i,i)>0
