    varc=(nav.pclk(idx).std(sat)*glc.CLIGHT-1E-3*t0)^2;
elseif t1>=0
    satclk=c1;
    if satclk==0,stat=0;return;end
    varc=(nav.pclk(idx+1).std(sat)*glc.CLIGHT+1E-3*t1)^2;
elseif c0~=0 && c1~=0
    satclk=(c1*t0-c0*t1)/(t0-t1);
