        varc=(nav.pclk(idx+1).std(sat)*glc.CLIGHT+1E-3*abs(t1))^2;
    else
        varc=(nav.pclk(idx).std(sat)*glc.CLIGHT+1E-3*abs(t0))^2;
    end
else
    stat=0; return;
end

if satclk~=0
    satclk0=satclk;
    varc0=varc;
end

return

