        week=week+1; sow=0;
    end
    str_time=sprintf('%4d%s%10.3f',week,sep,sow);
elseif solopt.timef==glc.SOLT_UTC
    if (1-sol.time.sec)<0.5/1e3
        sol.time.time=sol.time.time+1;
        sol.time.sec=0;
