    if sys==glc.SYS_BDS
        if prn<19 %BD2
            if ~bds_frq_flag,continue;end
            frq=opt.bd2frq;
            for j=1:glc.NFREQ
               nav.lam(i,j)=lam(i,frq(j)); 
            end
        else %BD3
            if ~bds_frq_flag,continue;end
            frq=opt.bd3frq;
            for j=1:glc.NFREQ
                nav.lam(i,j)=lam(i,frq(j)); 
            end
        end
    else %GPS GLO GAL QZS
        nav.lam(i,:)=lam(i,1:3);
    end
end

return

