            end
        elseif flag==3||flag==4
            continue;
        end
        i=i+1;
        if i>nsat,break,end
    end

    % save data to obs struct
    if ndata==0,continue;end
    for i=1:ndata
        if headinfo.tsys==glc.TSYS_UTC
            data(i).time=utc2gpst(data(i).time);
        end
        [data(i),slips]=saveslips(data(i),slips);
