for i=1:ns
    fid=fopen(fname);
    sta_name=upper(sta(i).name);
    while ~feof(fid)
        line=fgets(fid);
        if ~isempty(strfind(line,'-cmc')),break;end
    end

    while ~feof(fid)
        line=fgets(fid);
        if ~isempty(strfind(line,'$$'))||size(line,2)<=2,continue;end 
        name=upper(line(3:6));
        if isempty(strfind(sta_name,name)),continue;end

        [otlp,fid,stat]=decode_blqdata(fid);

        if stat==1
            nav.otlp(:,:,i)=otlp';
        end
    end
    fclose(fid);
end

fprintf('over\n');

return

