    [week,sow]=time2gpst(solution(i).time);
    time(n+1)=sow;
    pos_mea(n+1,:)=[week,sow,solution(i).pos];
    n=n+1;
end

[~,Cne]=xyz2blh(pos_ref(1,3:5));

n=size(pos_mea,1); j=0; 
