for i=1:n
    if dot(pos_mea(i,1:3),pos_mea(i,1:3))<=0
        continue;
    end
    time=pos_mea(i,2);
    idx=find(abs(pos_ref(:,2)-time)<0.1);
    if any(idx)
        t(j+1,:)=time;
        pos1(j+1,:)=Cne*pos_mea(i,3:5)';
        pos2(j+1,:)=Cne*pos_ref(idx,3:5)';
        j=j+1;
    end
end

if j==0
    error('Solution is empty!!!\n');
end

if j<n
    t(j+1:end,:)=[]; pos1(j+1:end,:)=[]; pos2(j+1:end,:)=[];
end

