function dr=tide_solid(pos,Cne,rsun,rmoon,gmst,opt)

GMS=1.327124E+20; %sun gravitational constant
GMM=4.902801E+12; %moon gravitational constant
eu(1)=Cne(3);eu(2)=Cne(6);eu(3)=Cne(9);

% step1:time domain
dr1=tide_pl(eu,rsun,GMS,pos);
dr2=tide_pl(eu,rmoon,GMM,pos);

% step2:frequency domain, only K1 radial
sin21=sin(2*pos(1));
du=-0.012*sin21*sin(gmst+pos(2));

dr(1)=dr1(1)+dr2(1)+du*Cne(3);
dr(2)=dr1(2)+dr2(2)+du*Cne(6);
dr(3)=dr1(3)+dr2(3)+du*Cne(9);

% eliminate permanent deformation
if bitand(opt,8)
    sin1=sin(pos(1));
    du=0.1196*(1.5*sin1*sin1-0.5);
    dn=0.0247*sin21;
    dr(1)=dr(1)+du*Cne(3)+dn*Cne(2);
    dr(2)=dr(2)+du*Cne(6)+dn*Cne(5);
    dr(3)=dr(3)+du*Cne(9)+dn*Cne(8);
end

return

function dr=tide_pl(eu,rp,GMp,pos)

global glc
GME=3.986004415E+14; %earth gravitational constant
H3=0.292; L3=0.015;
dr=zeros(3,1);

r=norm(rp);
if r<=0,return;end

ep=rp/r;

K2=GMp/GME*glc.RE_WGS84^4/r^3;
K3=K2*glc.RE_WGS84/r;
latp=asin(ep(3)); lonp=atan2(ep(2),ep(1));
cosp=cos(latp); sinl=sin(pos(1)); cosl=cos(pos(1));

%step1 in phase (degree2)
p=(3*sinl*sinl-1)/2;
H2=0.6078-0.0006*p;
L2=0.0847+0.0002*p;
a=dot(ep,eu);
dp=K2*3*L2*a;
du=K2*(H2*(1.5*a^2-0.5)-3*L2*a^2);

%step1 in phase (degree3)
dp=dp+K3*L3*(7.5*a^2-1.5);
du=du+K3*(H3*(2.5*a^3-1.5*a)-L3*(7.5*a^2-1.5)*a);

%step1 out-of-phase (only radial)
du=du+3.0/4.0*0.0025*K2*sin(2.0*latp)*sin(2.0*pos(1))*sin(pos(2)-lonp);
du=du+3.0/4.0*0.0022*K2*cosp*cosp*cosl*cosl*sin(2.0*(pos(2)-lonp));

dr(1)=dp*ep(1)+du*eu(1);
dr(2)=dp*ep(2)+du*eu(2);
dr(3)=dp*ep(3)+du*eu(3);

return

